import{_ as i,y as s,a as r,o as a,a2 as e,D as n}from"./chunks/framework.DCcmcJcL.js";const m=JSON.parse('{"title":"Customer Settings","description":"","frontmatter":{},"headers":[],"relativePath":"configure/settings.md","filePath":"configure/settings.md","lastUpdated":1789395222000}'),l={name:"configure/settings.md"};function c(g,t,h,d,u,p){const o=s("ImagePopup");return a(),r("div",null,[t[0]||(t[0]=e('<h1 id="customer-settings" tabindex="-1">Customer Settings <a class="header-anchor" href="#customer-settings" aria-label="Permalink to &quot;Customer Settings&quot;">​</a></h1><p>The <strong>Settings</strong> screen of the <strong>Customer</strong> group decides how customer accounts are created and signed in to, and whether the wishlist and the newsletter are offered.</p><p>Go to <strong>Configure &gt;&gt; Customer &gt;&gt; Settings</strong>.</p><h2 id="new-accounts" tabindex="-1">New accounts <a class="header-anchor" href="#new-accounts" aria-label="Permalink to &quot;New accounts&quot;">​</a></h2><ol><li>In <strong>Create New Account Options</strong>, choose the <strong>Default Group</strong> new customers are placed in. The default is <strong>General</strong>.</li><li>Switch <strong>Allow NewsLetter</strong> on to show a newsletter subscription checkbox on the sign-up form. It is on by default.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',5)),n(o,{src:"/images/configure/customer-settings.png",alt:"Create New Account Options, Email Verification and Login Options sections of the Customer Settings screen"}),t[1]||(t[1]=e('<p>Customer groups are described in <a href="./../customer/customer-group.html">Customer Groups</a>.</p><h2 id="email-verification" tabindex="-1">Email verification <a class="header-anchor" href="#email-verification" aria-label="Permalink to &quot;Email verification&quot;">​</a></h2><p>While <strong>Allow Email Verification</strong> is on, new customers receive an email with a verification link, and they can sign in only after they have opened it. It is off by default.</p><ol><li>In <strong>Email Verification</strong>, switch <strong>Allow Email Verification</strong> on or off.</li><li>Click <strong>Save Configuration</strong>.</li></ol><h2 id="sign-in-redirect" tabindex="-1">Sign-in redirect <a class="header-anchor" href="#sign-in-redirect" aria-label="Permalink to &quot;Sign-in redirect&quot;">​</a></h2><ol><li>In <strong>Login Options</strong>, set <strong>Redirect Customer to the selected page</strong> to where customers land after signing in: <strong>Home</strong> (the default) or <strong>Account</strong>, their account profile.</li><li>Click <strong>Save Configuration</strong>.</li></ol><h2 id="social-login" tabindex="-1">Social login <a class="header-anchor" href="#social-login" aria-label="Permalink to &quot;Social login&quot;">​</a></h2><p>Social login lets customers sign in with their Facebook, X (Twitter), Google, LinkedIn or GitHub account. The buttons of the providers you turn on appear on the storefront sign-in page. Before you start, create an app in the developer console of each provider to get its client ID and client secret.</p><ol><li>In <strong>Social Login</strong>, switch on the provider: <strong>Enable Facebook</strong>, <strong>Enable X (Twitter)</strong>, <strong>Enable Google</strong>, <strong>Enable LinkedIn</strong> or <strong>Enable GitHub</strong>. Its fields appear.</li><li>Enter the <strong>Client ID</strong> and <strong>Client Secret</strong> of your app.</li><li>Check the <strong>Redirect URL</strong>. Keep the path shown and change only the domain to your store&#39;s, such as <code>https://www.example.com/customer/social-login/google/callback</code>.</li><li>Add the same <strong>Redirect URL</strong> to your app&#39;s settings in the provider&#39;s developer console.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',9)),n(o,{src:"/images/configure/customer-social-login.png",alt:"Social Login section with Google turned on and its client ID, client secret and redirect URL fields"}),t[2]||(t[2]=e('<p>Each provider&#39;s switch is set per channel, while its client ID, client secret and redirect URL apply to the whole store.</p><h2 id="wishlist-and-newsletter" tabindex="-1">Wishlist and newsletter <a class="header-anchor" href="#wishlist-and-newsletter" aria-label="Permalink to &quot;Wishlist and newsletter&quot;">​</a></h2><ol><li>In <strong>Wishlist</strong>, switch <strong>Allow Wishlist option</strong> on or off.</li><li>In <strong>Newsletter Subscription</strong>, switch <strong>Allow Newsletter Subscription</strong> on or off.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p><strong>Allow Wishlist option</strong> lets shoppers save products to a wishlist. <strong>Allow Newsletter Subscription</strong> shows the subscription form in the storefront footer. Both are on by default.</p>',4))])}const w=i(l,[["render",c]]);export{m as __pageData,w as default};
